  (RUN("dem = 0\ndef f(n):\n    global dem\n    dem += 1\n    if n <= 1:\n        return 1\n    return f(n - 1) + f(n - 2)\nprint(f(5), dem)")+' (f(5)=8; 15 lần gọi)',),
  (RUN("def g(n):\n    if n == 0:\n        return\n    g(n - 1)\n    print(n, end=' ')\n    g(n - 1)\ng(3)")+' (đây chính là thứ tự chuyển đĩa theo cỡ)',),
